"use strict";const utils=require("../utils");module.exports=function(defaultFuncs,api,ctx){return async function pin(action,threadID,messageID,callback){let resolveFunc=()=>{};let rejectFunc=()=>{};const returnPromise=new Promise((resolve,reject)=>{resolveFunc=resolve;rejectFunc=reject});if(!callback){callback=(err,result)=>{if(err)return rejectFunc(err);resolveFunc(result)}}else{const _userCb=callback;callback=(err,result)=>{if(err){_userCb(err);return rejectFunc(err)}_userCb(null,result);resolveFunc(result)}}try{if(action==="list"){if(!threadID)throw new Error('Action "list" requires threadID.');const url=`https://www.facebook.com/messages/t/${threadID}/`;const allJsonData=await utils.json(url,ctx.jar,null,ctx.globalOptions,ctx);const lightReq=allJsonData&&allJsonData.__bbox&&allJsonData.__bbox.result&&allJsonData.__bbox.result.data&&allJsonData.__bbox.result.data.viewer&&allJsonData.__bbox.result.data.viewer.lightspeed_web_request;if(!lightReq||!lightReq.pin_status){utils.warn("pinMessage: No pinned messages found or pin_status missing.");return callback(null,[])}return callback(null,lightReq)}if(!ctx.mqttClient||!ctx.mqttClient.connected){throw new Error("MQTT not connected — call listenMqtt() first.")}if(!threadID||!messageID){throw new Error(`"${action}" requires threadID and messageID.`)}if(typeof ctx.wsReqNumber!=="number")ctx.wsReqNumber=0;if(typeof ctx.wsTaskNumber!=="number")ctx.wsTaskNumber=0;const epoch_id=parseInt(utils.generateOfflineThreadingID());const version_id="9523201934447612";const app_id=String(ctx.appID||ctx.mqttAppID||"2220391788200892");const createMqttRequest=(tasks,increment=0)=>({app_id:app_id,payload:JSON.stringify({epoch_id:epoch_id+increment,tasks:tasks,version_id:version_id}),request_id:++ctx.wsReqNumber,type:3});const publishMqtt=content=>new Promise((resolve,reject)=>{ctx.mqttClient.publish("/ls_req",JSON.stringify(content),{qos:1,retain:false},err=>{if(err)reject(err instanceof Error?err:new Error(String(err)));else resolve({success:true,request_id:content.request_id})})});if(action==="pin"){const pinTask={failure_count:null,label:"430",payload:JSON.stringify({thread_key:threadID,message_id:messageID,timestamp_ms:Date.now()}),queue_name:`pin_msg_v2_${threadID}`,task_id:++ctx.wsTaskNumber};const setSearchTask={failure_count:null,label:"751",payload:JSON.stringify({thread_key:threadID,message_id:messageID,pinned_message_state:1}),queue_name:"set_pinned_message_search",task_id:++ctx.wsTaskNumber};const results=await Promise.all([publishMqtt(createMqttRequest([pinTask],0)),publishMqtt(createMqttRequest([setSearchTask],1))]);return callback(null,{success:true,action:"pin",results:results})}if(action==="unpin"){const setSearchTask1={failure_count:null,label:"751",payload:JSON.stringify({thread_key:threadID,message_id:messageID,pinned_message_state:0}),queue_name:"set_pinned_message_search",task_id:++ctx.wsTaskNumber};const unpinTask={failure_count:null,label:"431",payload:JSON.stringify({thread_key:threadID,message_id:messageID,timestamp_ms:Date.now()}),queue_name:`unpin_msg_v2_${threadID}`,task_id:++ctx.wsTaskNumber};const setSearchTask2={failure_count:null,label:"751",payload:JSON.stringify({thread_key:threadID,message_id:messageID,pinned_message_state:0}),queue_name:"set_pinned_message_search",task_id:++ctx.wsTaskNumber};await publishMqtt(createMqttRequest([setSearchTask1],0));await publishMqtt(createMqttRequest([unpinTask],1));const result=await publishMqtt(createMqttRequest([setSearchTask2],2));return callback(null,{success:true,action:"unpin",result:result})}throw new Error(`Invalid action: "${action}". Use "pin", "unpin", or "list".`)}catch(err){utils.error("pinMessage",err);callback(err instanceof Error?err:new Error(String(err&&err.message?err.message:err)))}return returnPromise}};
